                <select [id]="'person-merge-into-' + p.id" data-testid="person-merge-into" #mergeInto
                  (change)="clearRowError(p.id)">
                  <option value="">Merge into</option>
                  @for (o of patronChoicesFor(p); track o.id) {
                    <option [value]="o.id">{{ o.name }}</option>
